mapper.select:
SELECT * FROM business_notifications
WHERE tenant_id = #{tenantId}
AND deleted = 0
ORDER BY created_at DESC
LIMIT #{limit}

SELECT * FROM business_notifications
WHERE tenant_id = #{tenantId}
AND created_at > #{afterTime}
AND deleted = 0
ORDER BY created_at DESC

mapper.update:
UPDATE business_notifications
SET deleted = 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
AND tenant_id IS NULL

UPDATE business_notifications
SET deleted = 1,
    updated_at = #{updatedAt}
WHERE tenant_id IS NOT NULL
AND notification_type = 'SYSTEM_NOTIFICATION'
AND title_en = #{titleEn}
AND title_zh = #{titleZh}
AND content_en = #{contentEn}
AND content_zh = #{contentZh}
AND deleted = 0
